const $=s=>document.querySelector(s),sleep=ms=>new Promise(r=>setTimeout(r,ms)),assert=(v,m)=>{if(!v)throw Error(m);};
const button=(i,a)=>`[data-deck="${i}"][data-action="${a}"]`,click=s=>{assert($(s),'Missing '+s);$(s).click();};
const files=['app.js','engine.js','keylock-shadow-live.js','pcm-resample.js','stem-bank-trace-155-harness.js','stem-activation-capture-145.js','vendor/signalsmith-stretch/SignalsmithStretch-open-play-replace.mjs','vendor/signalsmith-stretch/SignalsmithStretch-open-play-reference-dsp.mjs'];
const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(x=>x.toString(16).padStart(2,'0')).join('');
async function identities(){return Object.fromEntries(await Promise.all(files.map(async f=>{const r=await fetch(f,{cache:'no-store'});assert(r.ok,'Missing '+f);return[f,await hash(await r.arrayBuffer())];})));}
async function until(fn,label,ms=30000){const end=performance.now()+ms;while(!fn()){assert(performance.now()<end,label+' timed out');await sleep(10);}}
function base64(bytes){let s='';for(let i=0;i<bytes.length;i+=16384)s+=String.fromCharCode(...bytes.subarray(i,i+16384));return btoa(s);}
let app;
async function run(){
 const {engine,state}=app,decks=state.decks,track=decks[0].track,witnesses=[],adapters=[],ids=new WeakMap();let sequence=0,recording,transportRecording,timer;
 const r={checkpoint:150,diagnosticCheckpoint:155,startedAt:new Date().toISOString(),scope:'Four actual live keylocked decks, authored48second330/550Hz stereo original and three independent decoded Stem generations. Actual Play/pads/Stop, direct production attachStems, read-only actual worklet PCM/WASM capacity queries, 12second left-channel deck and original/old-bank/new-bank traces. Physical outputs muted. First capture ends before Stop. A separate six-second four-monitor capture covers third preparation, actual all-pad mute/restore and Stop. Not total process memory, CPU/deadline, right-channel acoustic, musical/model/native/hardware/reference acceptance.',criteria:{captureSeconds:12,minimum10msRMSRatio:.85,maximumAdjacentJump:.03,maximumNearZeroRunSeconds:.001,nearZeroAbsolute:1e-7,maximumRetainedWindowSourceSeconds:12,maximumWASMCapacityBytesPerWorklet:128*1024*1024},samples:[],generations:[],mainThreadTimerDelays:[],errors:[]};
 r.transportEvents=[];r.dspPolicy='Original-stereo analysis/phase reference for reserved18channels; published DSP retained for other geometries';r.adapterEvents=[];const labels=['deck0-monitor','deck1-monitor','deck2-monitor','deck3-monitor','deck1-original','deck1-bank0-melody','deck1-bank1-melody'];r.calls=[];const methods=[];
 const id=b=>{if(!ids.has(b))ids.set(b,++sequence);return ids.get(b);};
 function decoded(){const owners=[];const add=(owner,buffer)=>{if(buffer)owners.push({owner,id:id(buffer),bytes:buffer.length*buffer.numberOfChannels*4});};add('engine-original',engine.buffers.get(track.id));for(const [i,b]of(engine.stemBuffers.get(track.id)||[]).entries())add('engine-cache-'+i,b);for(const [i,a]of adapters.entries())for(const [j,s]of a.sources.entries())add(`deck${i}-source${j}`,s.buffer);const unique=new Map(owners.map(o=>[o.id,o.bytes]));return{owners,uniqueBuffers:unique.size,uniqueDecodedBytes:[...unique.values()].reduce((a,b)=>a+b,0)};}
 async function sample(label){const entry={label,at:engine.ctx.currentTime,wall:performance.now(),decks:[],decoded:decoded(),jsHeap:performance.memory?{usedJSHeapSize:performance.memory.usedJSHeapSize,totalJSHeapSize:performance.memory.totalJSHeapSize,jsHeapSizeLimit:performance.memory.jsHeapSizeLimit}:null};for(const [i,a]of adapters.entries()){const before=a.snapshot(),group=a.active,node=group?.nodes?.[0];let remote=null;if(node)remote=await node.resourceSnapshot();const after=a.snapshot();entry.decks.push({index:i,before,remote,after});}r.samples.push(entry);return entry;}
 async function generation(n){const sr=44100,next=Array.from({length:4},()=>engine.ctx.createBuffer(2,sr*48,sr));for(let c=0;c<2;c++)next[1].copyToChannel(engine.buffers.get(track.id).getChannelData(c),c);const item={generation:n,bufferIDs:next.map(id),startedAt:engine.ctx.currentTime};await engine.attachStems(track,next,decks);item.returnedAt=engine.ctx.currentTime;item.banks=adapters.map(a=>a.activeStemBank);item.sameOwners=adapters.map((a,i)=>engine.voices.get(i)?.liveKeylock===a);assert(item.sameOwners.every(Boolean),'Generation replaced live owners');r.generations.push(item);if(n===1)for(let i=0;i<4;i++)click(button(i,'pad')+'[data-pad="0"]');await sample('generation-'+n);}
 $('#resource-run').disabled=true;
 try{
  r.sourceBefore=await identities();engine.init();engine.audioMonitor.mutePhysical(true);await engine.resume();assert(engine.audioMonitor.snapshot().physicalMuted,'Physical mute');await until(()=>!state.analysis,'Analysis');for(const d of decks)engine.pause(d);
  for(const unit of state.fx)for(const slot of unit)slot.on=false;engine.configureFX(state.fx,state.fxRoutes||[],decks.map(d=>(d.track?.bpm||120)*d.rate),state.fxTempo);
  const original=engine.ctx.createBuffer(2,44100*48,44100);for(let c=0;c<2;c++)for(let n=0;n<original.length;n++)original.getChannelData(c)[n]=.06*Math.sin(2*Math.PI*(c?550:330)*n/44100);engine.buffers.set(track.id,original);engine.stemBuffers.delete(track.id);Object.assign(track,{duration:48,bpm:120,grid:0,gridWarpMarkers:[],gridMarkers:[],analyzed:true});r.originalHashes=await Promise.all([0,1].map(c=>hash(original.getChannelData(c).buffer)));
  const count=$('#deck-count');count.value='4';count.dispatchEvent(new Event('change',{bubbles:true}));assert(state.deckCount===4,'Actual4deck UI');
  for(const [i,d]of decks.entries()){Object.assign(d,{track,position:1,rate:[1,1.1,.8,1.25][i],keylock:true,keyShift:[0,3,-2,0][i],reverse:false,loop:false,slip:false,stemSlip:'off',sync:false,mode:'INT',stems:[true,true,true,true],stemFX:[false,false,false,false]});engine.clearDeckScratchCache(i);engine.mix(i,'level',.3);}
  await engine.ctx.audioWorklet.addModule(new URL('./stem-activation-capture-145.js',import.meta.url));for(let i=0;i<4;i++){const split=engine.ctx.createChannelSplitter(2);engine.nodes[i].monitorTap.connect(split);const w=new AudioWorkletNode(engine.ctx,'open-play-stem-activation-145-test',{numberOfInputs:1,numberOfOutputs:1,outputChannelCount:[1],channelCount:1,channelCountMode:'explicit',channelInterpretation:'discrete'});split.connect(w,0);w.connect(engine.ctx.destination);witnesses.push(w);}
  for(let i=0;i<4;i++){click(button(i,'tab')+'[data-tab="Stems"]');click(button(i,'play'));await until(()=>decks[i].playing&&!decks[i].processing,'Play '+i);const a=engine.voices.get(i).liveKeylock;assert(a?.reservedStems&&a.active.nodes[0].resourceSnapshot,'Actual live resource RPC');adapters.push(a);}
  for(const [i,a]of adapters.entries()){const node=a.active.nodes[0],method=node.replaceBufferChannels;const onEvent=a.onEvent;methods.push({node,method,adapter:a,onEvent});a.onEvent=event=>{onEvent(event);if(['stem-bank-warming','stems-replaced','error','ended'].includes(event.type))r.adapterEvents.push({deck:i,at:engine.ctx.currentTime,event});};node.replaceBufferChannels=async(...args)=>{const submittedAt=engine.ctx.currentTime,head=args[2][2]?.slice(0,8),tail=args[2][2]?.slice(-8);const ack=await method(...args);r.calls.push({deck:i,submittedAt,acknowledgedAt:engine.ctx.currentTime,...ack,melodyLeftHead:head?[...head]:null,melodyLeftTail:tail?[...tail]:null});return ack;};}
  for(const output of [adapters[1].outputs[0],adapters[1].active.gains[2],adapters[1].active.gains[6]]){const split=engine.ctx.createChannelSplitter(2);output.connect(split);const w=new AudioWorkletNode(engine.ctx,'open-play-stem-activation-145-test',{numberOfInputs:1,numberOfOutputs:1,outputChannelCount:[1],channelCount:1,channelCountMode:'explicit',channelInterpretation:'discrete'});split.connect(w,0);w.connect(engine.ctx.destination);witnesses.push(w);}
  r.sampleRate=engine.ctx.sampleRate;r.transport=decks.map(d=>({rate:d.rate,keyShift:d.keyShift,keylock:d.keylock}));await sleep(200);await sample('initial');
  r.captureStartedAt=engine.ctx.currentTime;r.captureWallStart=performance.now();recording=Promise.all(witnesses.map((w,i)=>new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(Error('Capture timeout '+i)),34000);w.port.onmessage=({data})=>{if(data.type==='done'){clearTimeout(timeout);resolve(data);}};w.port.postMessage({type:'capture',id:'resource',frames:Math.round(12*engine.ctx.sampleRate)});})));let previous=performance.now();timer=setInterval(()=>{const at=performance.now();r.mainThreadTimerDelays.push({at,audioTime:engine.ctx.currentTime,excessMilliseconds:at-previous-25,deck1StemGains:engine.voices.get(1)?.stemGains.map(g=>g.gain.value)||[],bankGains:adapters[1].stemBankGates.map(bank=>bank.map(g=>g.gain.value)),groupGains:adapters[1].active.gains.map(g=>g.gain.value)});previous=at;},25);
  for(const [n,target]of[[1,2],[2,8]]){while(engine.ctx.currentTime<r.captureStartedAt+target){await sample('periodic');await sleep(500);}$('#resource-status').textContent=`Four decks running; preparing generation ${n}/3…`;await generation(n);}
  while(engine.ctx.currentTime<r.captureStartedAt+10.8){await sample('periodic');await sleep(500);}r.preCaptureEnd=await sample('pre-capture-end');const packets=await recording;r.captureWallEnd=performance.now();
  for(const w of witnesses.slice(4)){w.disconnect();w.port.close();}
  r.transportCaptureStartedAt=engine.ctx.currentTime;
  transportRecording=Promise.all(witnesses.slice(0,4).map((w,i)=>new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(Error('Transport capture timeout '+i)),16000);w.port.onmessage=({data})=>{if(data.type==='done'){clearTimeout(timeout);resolve(data);}};w.port.postMessage({type:'capture',id:'transport155',frames:Math.round(6*engine.ctx.sampleRate)});})));
  await generation(3);await sleep(300);
  r.transportEvents.push({type:'mute',at:engine.ctx.currentTime});for(let i=0;i<4;i++)for(const pad of[1,2,3])click(button(i,'pad')+'[data-pad="'+pad+'"]');assert(decks.every(d=>d.stems.every(v=>!v)),'All Stems pads muted');await sleep(300);
  r.transportEvents.push({type:'restore',at:engine.ctx.currentTime});for(let i=0;i<4;i++)for(const pad of[1,2,3])click(button(i,'pad')+'[data-pad="'+pad+'"]');assert(decks.every(d=>!d.stems[0]&&d.stems.slice(1).every(Boolean)),'Stems pads restored');await sleep(300);
  r.beforeStop=await sample('before-stop');r.stopAt=engine.ctx.currentTime;for(let i=0;i<4;i++)click(button(i,'play'));await until(()=>decks.every(d=>!d.playing),'All stopped');
  const transportPackets=await transportRecording;r.transportPcm=await Promise.all(transportPackets.map(async(p,i)=>({deck:i,trace:'deck'+i+'-transport',channel:0,startFrame:p.startFrame,frames:p.data.length,quanta:p.quanta,errors:p.errors,sha256:await hash(p.data.buffer),base64:base64(new Uint8Array(p.data.buffer))})));
  await Promise.all(adapters.map(a=>a.dispose()));r.afterStop=await sample('after-stop');engine.stemBuffers.delete(track.id);r.afterCacheClear=await sample('after-cache-clear');
  r.pcm=await Promise.all(packets.map(async(p,i)=>({deck:i<4?i:1,trace:labels[i],channel:0,startFrame:p.startFrame,frames:p.data.length,quanta:p.quanta,errors:p.errors,sha256:await hash(p.data.buffer),base64:base64(new Uint8Array(p.data.buffer))})));r.originalUnchanged=JSON.stringify(r.originalHashes)===JSON.stringify(await Promise.all([0,1].map(c=>hash(original.getChannelData(c).buffer))));assert(r.originalUnchanged,'Original mutated');r.workflowExecuted=true;
 }catch(error){r.errors.push({message:error.message,stack:error.stack});if(transportRecording&&!r.transportPcm)try{const tp=await transportRecording;r.transportPcm=await Promise.all(tp.map(async(p,i)=>({deck:i,trace:'deck'+i+'-transport',channel:0,startFrame:p.startFrame,frames:p.data.length,quanta:p.quanta,errors:p.errors,sha256:await hash(p.data.buffer),base64:base64(new Uint8Array(p.data.buffer))})));}catch(e){r.errors.push({transportCaptureError:e.message});}if(recording&&!r.pcm)try{const packets=await recording;r.pcm=await Promise.all(packets.map(async(p,i)=>({deck:i<4?i:1,trace:labels[i],channel:0,startFrame:p.startFrame,frames:p.data.length,quanta:p.quanta,errors:p.errors,sha256:await hash(p.data.buffer),base64:base64(new Uint8Array(p.data.buffer))})));}catch(e){r.errors.push({captureError:e.message});}}
 finally{clearInterval(timer);for(const {node,method,adapter,onEvent}of methods){node.replaceBufferChannels=method;adapter.onEvent=onEvent;}for(const d of decks)engine.pause(d);await Promise.allSettled(adapters.map(a=>a.dispose()));for(const w of witnesses){w.disconnect();w.port.close();}r.sourceAfter=await identities();r.sourceStable=JSON.stringify(r.sourceBefore)===JSON.stringify(r.sourceAfter);r.workflowCompleted=!!r.workflowExecuted&&!r.errors.length&&r.sourceStable;r.finishedAt=new Date().toISOString();const raw=JSON.stringify(r),ident=crypto.randomUUID().replaceAll('-','');let receipt;
  try{const response=await fetch('/api/test-evidence/stem-resource-150/'+ident,{method:'POST',headers:{'Content-Type':'application/json','X-Open-Play':'local-prototype'},body:raw});assert(response.ok,'Evidence save failed');receipt=await response.json();assert(receipt.sha256===await hash(new TextEncoder().encode(raw))&&receipt.bytes===new TextEncoder().encode(raw).byteLength,'Evidence receipt mismatch');}
  catch(error){receipt={error:error.message,id:ident};const link=$('#resource-download');link.href=URL.createObjectURL(new Blob([raw],{type:'application/json'}));link.download=ident+'.json';link.hidden=false;}
  const summary={workflowCompleted:r.workflowCompleted,sourceStable:r.sourceStable,errors:r.errors,samples:r.samples.length,generations:r.generations.map(g=>({generation:g.generation,banks:g.banks,sameOwners:g.sameOwners})),receipt};$('#resource-original').textContent=JSON.stringify(summary);$('#resource-results').textContent=JSON.stringify(summary,null,2);$('#resource-status').textContent=receipt.error?'Evidence export failed; stopped; use original download':r.workflowCompleted?'Bank trace saved privately; stopped; independent inspection required':'Failed workflow retained privately: '+r.errors.map(e=>e.message).join('; ');}
}
async function boot(){const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const n of [...parsed.body.children])if(n.tagName!=='SCRIPT')document.body.append(n);await import('./app.js');await until(()=>window.openPlay?.state.decks[0].track,'Actual app');app=window.openPlay;$('#resource-run').disabled=false;$('#resource-status').textContent='Ready';}
$('#resource-run').onclick=()=>run();boot().catch(e=>$('#resource-status').textContent=e.message);
